update cms_template_library set use_num = ifnull(use_num, 0) + 1
where id = #{libraryId}
  and not exists (
      select 1 from cms_member_template m
      where m.member_id = #{memberId}
        and m.original_template_id = #{libraryId}
        and m.id <> #{memberTemplateId}
  )

