SELECT mt.id, mt.member_id,mt.member_template_id, mt.category_id, mt.title, mt.description, mt.img_url,mt.players,mt.usage_location,mt.required_materials, mt.duration, mt.difficulty, mt.is_sync, mt.rule_instructions, mt.validation_method, mt.sensor_type, mt.sensor_config, mt.question_name, mt.question_answer, mt.feedback_text, mt.coupon_id, mt.story_text, mt.story_img, mt.story_json, mt.hint1, mt.hint2, mt.answer_reveal, mt.photo_require_desc, mt.photo_review, mt.audio_url, mt.audio_duration, mt.question_a, mt.question_b, mt.question_c, mt.question_d, mt.correct_answer, mt.question_img, mt.question_audio, mt.question_option_media_json, mt.preference_json, mt.advanced_config_json, mt.activity_categoryids, mt.status, mt.publish_status, mt.reason, mt.del_flag, mt.rating,mt.use_num,mt.create_by, mt.create_time, mt.update_by, mt.update_time, c.category_name, c.icon, (select original.interaction_type from cms_member_template original where original.id = mt.member_template_id and original.member_id = mt.member_id) as interaction_type FROM cms_template_library mt LEFT JOIN sys_category c ON mt.category_id = c.id WHERE mt.del_flag = 0 AND mt.publish_status = 1 AND c.del_flag = 0 AND c.status = 1 AND mt.category_id IN
#{categoryId}
ORDER BY mt.create_time DESC

