update cms_template_library set status = #{row.status},
    publish_status = #{row.publishStatus}, reason = #{row.reason}, update_time = now()
where id = #{row.id} and member_id = #{ownerId} and del_flag = 0 and status = 0 and member_template_id = #{row.memberTemplateId}

update cms_template_library set status = 0, publish_status = 0, update_time = now()
where id = #{id} and member_id = #{ownerId} and del_flag = 0 and member_template_id = #{memberTemplateId}
  and status = #{fromStatus} and publish_status = #{fromPublishStatus}
